947	    /**
948	     * Returns the leading {@code hexChars} upper-case hex characters of the SHA-256 digest of a
949	     * string, the form used by the derived owner codes (for example the customer code and household
950	     * identifier). The digest itself comes from {@link Owner#sha256Hex(String)}, the single
951	     * definition of the SHA-256 hex derivation; this method only takes its leading characters and
952	     * upper-cases them, so {@code hexChars} characters cover the leading {@code ceil(hexChars / 2)}
953	     * bytes of the digest.
954	     *
955	     * @param input the string to hash
956	     * @param hexChars the number of leading upper-case hex characters to return
957	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
958	     */
959	    private String shaHex(String input, int hexChars) {
960	        return Owner.sha256Hex(input).substring(0, hexChars).toUpperCase(java.util.Locale.ROOT);
961	    }
