963	    /**
964	     * Returns the owners that belong to the household identified by the given {@code householdId},
965	     * i.e. every owner carrying that exact identifier. Soft-deleted owners are included, so a caller
966	     * that must ignore deleted owners (as {@link #rejectDuplicateIdentity(OwnerFieldsDto)} does)
967	     * filters them out itself. The owners are taken from the current set, so after a create the
968	     * result includes the newly persisted owner. An owner without a household (a {@code null}
969	     * identifier) belongs to no shared household, so an empty list is returned. This is the single
970	     * definition of a household's members, shared by every rule that reasons about the owners
971	     * sharing a household (the household-duplicate block and the household member count).
972	     *
973	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
974	     * @return the owners in the household, or an empty list when {@code householdId} is {@code null}
975	     */
976	    private List<Owner> householdMembers(String householdId) {
977	        if (householdId == null) {
978	            return List.of();
979	        }
