1000	     * Stamps an owner with its household member count, the number of owners sharing its household
1001	     * (see {@link #countHouseholdMembers(String)}), so every value the owner derives from its
1002	     * household size (its membership factor and level) reads a populated count rather than the
1003	     * unstamped default. This is the single definition of hydrating an owner with its household
1004	     * member count, shared by the create and read paths that render an owner's derived values.
1005	     *
1006	     * @param owner the owner to stamp, mutated in place with its household member count
1007	     */
1008	    private void applyHouseholdMemberCount(Owner owner) {
1009	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1010	    }
1011	
1012	    /**
1013	     * Resolves the household level ceiling a newly created owner is subject to: one above the
1014	     * current maximum {@code membershipLevel} among the existing, non-deleted owners already
1015	     * sharing its household (see {@link #householdMembers(String)}). Each existing member is
1016	     * stamped with its household member count first so its {@link Owner#getMembershipLevel()}
1017	     * reads a populated count, mirroring how the create and read paths render a member's derived
1018	     * level. The ceiling is taken before the new owner is persisted, so it reflects only the
1019	     * members already in the household. When the owner joins an empty household — no household
1020	     * identifier, or no existing member — no ceiling applies and {@code null} is returned, letting
1021	     * the owner earn its uncapped level (see {@link Owner#cappedMembershipLevel(int, Integer)}).
1022	     *
1023	     * @param householdId the shared household identifier of the owner being created, or {@code null}
1024	     * @return one above the household's current maximum membership level, or {@code null} when no ceiling applies
1025	     */
1026	    private Integer householdMembershipLevelCap(String householdId) {
1027	        java.util.OptionalInt max = householdMembers(householdId).stream()
1028	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1029	            .peek(this::applyHouseholdMemberCount)
1030	            .mapToInt(Owner::getMembershipLevel)
1031	            .max();
1032	        return max.isPresent() ? max.getAsInt() + 1 : null;
1033	    }
1034	
1035	    /**
1036	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
1037	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
1038	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
1039	     *
1040	     * @param value the value to collapse, or {@code null}
1041	     * @return the whitespace-collapsed value, never {@code null}
1042	     */
1043	    private String collapseWhitespace(String value) {
1044	        if (value == null) {
1045	            return "";
1046	        }
1047	        return value.trim().replaceAll("\\s+", " ");
1048	    }
1049	
1050	    /**
1051	     * Common street-type abbreviations expanded during address normalization, keyed by their
1052	     * upper-cased token.
1053	     */
1054	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
1055	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
1056	
1057	    /**
1058	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
1059	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1060	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1061	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1062	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1063	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1064	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1065	     * everywhere an address is stored or compared.
1066	     *
1067	     * @param address the submitted address value, or {@code null}
1068	     * @return the normalized address, never {@code null}
1069	     */
1070	    private String normalizeAddress(String address) {
1071	        if (address == null) {
1072	            return "";
1073	        }
1074	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1075	        if (collapsed.isEmpty()) {
1076	            return "";
1077	        }
1078	        String[] tokens = collapsed.split(" ");
1079	        StringBuilder sb = new StringBuilder(collapsed.length());
1080	        for (int i = 0; i < tokens.length; i++) {
1081	            if (i > 0) {
1082	                sb.append(' ');
1083	            }
1084	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1085	        }
1086	        return sb.toString();
1087	    }
1088	}
