328	    /**
329	     * Computes the full lower-case hex SHA-256 digest of a string: the input is hashed as UTF-8
330	     * bytes and each of the 32 digest bytes is rendered as two lower-case hex digits, yielding a
331	     * 64-character string. This is the single definition of the SHA-256 hex derivation shared by
332	     * every rule that hashes owner fields (for example the customer code and household identifier,
333	     * each formed from the leading upper-case characters of this digest). SHA-256 is a required
334	     * platform algorithm; were it ever unavailable an {@link IllegalStateException} is thrown.
335	     *
336	     * @param input the string to hash
337	     * @return the 64-character lower-case hex SHA-256 digest of {@code input}
338	     */
339	    public static String sha256Hex(String input) {
340	        try {
341	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
342	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
343	            StringBuilder sb = new StringBuilder(digest.length * 2);
344	            for (byte b : digest) {
345	                sb.append(String.format("%02x", b));
346	            }
347	            return sb.toString();
348	        }
349	        catch (java.security.NoSuchAlgorithmException e) {
350	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
351	        }
352	    }
353	
354	    /**
355	     * Fixed telephone country-code table: the exact national-number length (the count of digits
356	     * following the country code) each country code this application recognizes admits
357	     * ({@code '61'} Australia => 9, {@code '1'} NANP => 10). Keyed by the country-code digits
358	     * without the leading {@code '+'}. A country code absent from this table is not recognized.
359	     */
360	    private static final Map<String, Integer> COUNTRY_CODE_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
361	
362	    /**
363	     * Resolves the recognized country code a normalized E.164 telephone carries: the longest entry
364	     * of the fixed country-code table (see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}) whose digits the
365	     * number begins with, so a shorter code can never shadow a longer one. Returns the country-code
366	     * digits without the leading {@code '+'} (for example {@code '61'} for {@code '+61412345678'}),
367	     * or {@code null} when the value is {@code null}, carries no leading {@code '+'}, or begins with
368	     * no recognized country code. This is the single definition of how an E.164 telephone splits
369	     * from its country code, shared by every rule that reasons about a telephone's country code.
370	     *
371	     * @param telephone the normalized E.164 telephone (a {@code '+'} followed by digits), or {@code null}
372	     * @return the recognized country-code digits, or {@code null} when none is recognized
373	     */
374	    public static String countryCodeOf(String telephone) {
375	        if (telephone == null || !telephone.startsWith("+")) {
376	            return null;
377	        }
378	        String digits = telephone.substring(1);
379	        return COUNTRY_CODE_NATIONAL_LENGTHS.keySet().stream()
380	            .filter(digits::startsWith)
381	            .max(Comparator.comparingInt(String::length))
382	            .orElse(null);
383	    }
384	
385	    /**
386	     * Resolves the exact national-number length (the count of digits following the country code) a
387	     * recognized country code admits using the fixed country-code table ({@code '61'} => 9,
388	     * {@code '1'} => 10, see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}). Returns the length, or
389	     * {@code null} when the country code is {@code null} or not recognized (it then carries no
390	     * per-country length rule). This is the single definition of the per-country national-number
391	     * lengths, shared by every rule that relates a telephone's national number to its country code.
392	     *
393	     * @param countryCode the country-code digits without the leading {@code '+'}, or {@code null}
394	     * @return the required national-number length, or {@code null} when the code is not recognized
395	     */
396	    public static Integer nationalNumberLength(String countryCode) {
397	        return countryCode == null ? null : COUNTRY_CODE_NATIONAL_LENGTHS.get(countryCode);
398	    }
399	
400	    /**
401	     * Fixed city-to-region table: the canonical region each known city belongs to
402	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). A city
403	     * absent from this table has no known region.
404	     */
405	    private static final Map<String, String> CITY_REGIONS = Map.of(
406	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
407	
408	    /**
409	     * Resolves the canonical region a city belongs to using the fixed city-to-region table
410	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns the
411	     * region string, or {@code null} when the city has no known region. This is the single
412	     * definition of the city-to-region mapping, shared by every rule that derives a region
413	     * from an owner's city.
414	     *
415	     * @param city the city to resolve
416	     * @return the canonical region, or {@code null} when the city has no known region
417	     */
418	    public static String regionForCity(String city) {
419	        return CITY_REGIONS.get(city);
420	    }
421	
422	    /**
423	     * Fixed region-to-postcode table: the inclusive {@code {low, high}} 4-digit postcode range
424	     * each region admits ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
425	     * A region absent from this table has no fixed range.
426	     */
427	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
428	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
429	
430	    /**
431	     * Resolves the inclusive {@code {low, high}} 4-digit postcode range a region admits using the
432	     * fixed region-to-postcode table ({@code NSW 2000-2099}, {@code VIC 3000-3099},
433	     * {@code QLD 4000-4099}). Returns the range, or {@code null} when the region is {@code null} or
434	     * has no fixed range (any 4-digit postcode is then admitted). This is the single definition of
435	     * the region-to-postcode ranges, shared by every rule that relates a postcode to a region.
436	     *
437	     * @param region the region to resolve, or {@code null}
438	     * @return the inclusive {@code {low, high}} range, or {@code null} when the region has none
439	     */
440	    public static int[] postcodeRangeForRegion(String region) {
441	        return region == null ? null : REGION_POSTCODE_RANGES.get(region);
442	    }
443	
444	    /**
445	     * Resolves the canonical region a postcode belongs to by finding the fixed region-to-postcode
446	     * range that contains it ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
447	     * Returns the region string, or {@code null} when the postcode is {@code null}, not a 4-digit
448	     * value, or falls in no known range. This is the single definition of the postcode-to-region
449	     * mapping, shared by every rule that derives a region from a postcode.
450	     *
451	     * @param postcode the postcode to resolve
452	     * @return the canonical region, or {@code null} when the postcode maps to no known region
453	     */
454	    public static String regionForPostcode(String postcode) {
455	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
456	            return null;
457	        }
458	        int value = Integer.parseInt(postcode);
459	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
460	            int[] range = entry.getValue();
461	            if (value >= range[0] && value <= range[1]) {
462	                return entry.getKey();
463	            }
464	        }
465	        return null;
466	    }
467	
468	    /**
469	     * Returns the canonical region this owner belongs to. The owner's {@code postcode} is preferred:
470	     * when it falls in a known region range (see {@link #regionForPostcode(String)}) that region is
471	     * used, disambiguating cities that share a name. Only when the postcode is absent or in no known
472	     * range does derivation fall back to the fixed city-to-region table (see
473	     * {@link #regionForCity(String)}). Returns {@code null} when neither the postcode nor the city
474	     * resolves to a known region. This is the single definition of an owner's region, shared by
475	     * every rule that derives a region from an owner.
476	     *
477	     * @return the owner's canonical region, or {@code null} when it has no known region
478	     */
479	    @Transient
480	    public String getRegion() {
481	        String region = regionForPostcode(this.postcode);
482	        return region != null ? region : regionForCity(this.city);
483	    }
484	
485	    /**
486	     * Resolves whether an {@code email} counts as present for membership purposes: the value is
487	     * non-null and not blank. Returns {@code false} otherwise. This is the single definition of an
488	     * owner "having an email", shared by every rule that turns email presence into a derived value
489	     * (its membership factor and its {@code contactPreference}).
490	     *
491	     * @param email the owner's email, or {@code null}
492	     * @return {@code true} when the email is present and not blank
493	     */
494	    public static boolean hasEmail(String email) {
495	        return email != null && !email.isBlank();
496	    }
497	
498	    /**
499	     * Resolves whether an owner with the given {@code namesakeCount} has no namesakes: the count is
500	     * present and equal to {@code 0}. Returns {@code false} when the count is {@code null} (unknown)
501	     * or positive. This is the single definition of the "no namesakes" membership factor, shared by
502	     * every rule that rewards an owner for being unique by name.
503	     *
504	     * @param namesakeCount the owner's namesake count, or {@code null}
505	     * @return {@code true} when the owner is known to have no namesakes
506	     */
507	    public static boolean hasNoNamesakes(Integer namesakeCount) {
508	        return namesakeCount != null && namesakeCount == 0;
509	    }
510	
511	    /**
512	     * Resolves the fiscal year a date falls in. The fiscal year starts on 1 July, so a date in July
513	     * through December belongs to the fiscal year of the following calendar year, while a date in
514	     * January through June belongs to the fiscal year of its own calendar year (for example both
515	     * 2025-08-01 and 2026-03-01 fall in fiscal year 2026). This is the single definition of the
516	     * date-to-fiscal-year mapping, shared by every value derived on a fiscal-year basis (the
517	     * {@code fiscalYear}, the membership number's year segment and tenure).
518	     *
519	     * @param date the date to resolve, never {@code null}
520	     * @return the fiscal year the date falls in
521	     */
522	    public static int fiscalYearOf(LocalDate date) {
523	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
524	    }
525	
526	    /**
527	     * Resolves whether an owner registered on {@code registrationDate} has long tenure as of
528	     * {@code asOf}: the number of elapsed fiscal years between the two dates (see
529	     * {@link #fiscalYearOf(LocalDate)}) exceeds {@code 1}. Returns {@code false} when
530	     * {@code registrationDate} is absent, so the owner has no derivable tenure; because a newly
531	     * created owner has zero elapsed fiscal years, it never counts as long-tenured. This is the
532	     * single definition of the "long tenure" membership factor, shared by every rule that rewards
533	     * an owner for tenure beyond a fiscal year.
534	     *
535	     * @param registrationDate the owner's registration date, or {@code null}
536	     * @param asOf the date the tenure is measured against
537	     * @return {@code true} when the owner's tenure exceeds one elapsed fiscal year
538	     */
539	    public static boolean hasLongTenure(LocalDate registrationDate, LocalDate asOf) {
540	        return registrationDate != null && fiscalYearOf(asOf) - fiscalYearOf(registrationDate) > 1;
541	    }
542	
543	    /**
544	     * Resolves whether an owner with the given {@code householdMemberCount} belongs to a large
545	     * household: the count is present and at least {@code 3}. Returns {@code false} when the count is
546	     * {@code null} (unknown) or smaller. This is the single definition of the "large household"
547	     * membership factor, shared by every rule that rewards an owner for a household of three or more.
548	     *
549	     * @param householdMemberCount the number of owners sharing the household, or {@code null}
550	     * @return {@code true} when the owner is known to belong to a household of three or more
551	     */
552	    public static boolean hasLargeHousehold(Integer householdMemberCount) {
553	        return householdMemberCount != null && householdMemberCount >= 3;
554	    }
555	
556	    /**
557	     * Returns this owner's membership points. Points start at {@code 0} and accumulate the membership
558	     * factors: {@code 2} when an email is present, {@code 1} when the owner has no namesakes
559	     * (namesakeCount is 0), {@code 2} when the owner belongs to a household of three or more, and
560	     * {@code 3} when the owner's tenure exceeds one elapsed fiscal year. Because a newly created
561	     * owner has zero tenure, the tenure points are never awarded on creation. This is the single source the
562	     * membership level is derived from (see {@link #getMembershipLevel()}).
563	     *
564	     * @return the owner's membership points
565	     */
566	    @Transient
567	    public Integer getMembershipPoints() {
568	        LocalDate today = LocalDate.now();
569	        int points = 0;
570	        if (hasEmail(this.email)) {
571	            points += 2;
572	        }
573	        if (hasNoNamesakes(this.namesakeCount)) {
574	            points += 1;
575	        }
576	        if (hasLargeHousehold(this.householdMemberCount)) {
577	            points += 2;
578	        }
579	        if (hasLongTenure(this.registrationDate, today)) {
580	            points += 3;
581	        }
582	        return points;
583	    }
584	
585	    /**
586	     * Resolves the numeric membership level a given number of membership points earns: {@code 1} for
587	     * {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for
588	     * {@code 6} or more points. This is the single definition of the points-to-level mapping, shared
589	     * by every rule that derives a membership level from points (see {@link #getMembershipLevel()}).
590	     *
591	     * @param points the membership points to map
592	     * @return the membership level those points earn
593	     */
594	    public static int membershipLevelForPoints(int points) {
595	        if (points >= 6) {
596	            return 4;
597	        }
598	        if (points >= 4) {
599	            return 3;
600	        }
601	        if (points >= 2) {
602	            return 2;
603	        }
604	        return 1;
605	    }
606	
607	    /**
608	     * Applies an owner's household level ceiling to a membership level: the level is returned
609	     * unchanged when {@code cap} is {@code null} (no ceiling applies), otherwise it is capped at
610	     * {@code cap} so it can never exceed it. This is the single definition of how the household
611	     * level ceiling caps a membership level, shared by every rule that reads a capped membership
612	     * level (see {@link #getMembershipLevel()}).
613	     *
614	     * @param level the uncapped membership level derived from the owner's points
615	     * @param cap the owner's household level ceiling, or {@code null} when no ceiling applies
616	     * @return the membership level after applying the ceiling
617	     */
618	    public static int cappedMembershipLevel(int level, Integer cap) {
619	        return cap == null ? level : Math.min(level, cap);
620	    }
621	
622	    /**
623	     * Returns this owner's numeric membership level, derived from its membership points (see
624	     * {@link #getMembershipPoints()}) by the single points-to-level mapping (see
625	     * {@link #membershipLevelForPoints(int)}): {@code 1} for {@code 0-1} points, {@code 2} for
626	     * {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more points. The
627	     * result is then held to the owner's household level ceiling {@code membershipLevelCap} (see
628	     * {@link #cappedMembershipLevel(int, Integer)}): a new owner joining a household may earn a
629	     * level at most one above the highest level among its existing household members, and no
630	     * ceiling applies when the owner joined an empty household.
631	     *
632	     * @return the owner's membership level, capped by its household level ceiling
633	     */
634	    @Transient
635	    public Integer getMembershipLevel() {
636	        return cappedMembershipLevel(membershipLevelForPoints(getMembershipPoints()), this.membershipLevelCap);
637	    }
