639	    /**
640	     * Returns this owner's fiscal year formatted as {@code 'FY<YY>'}, where YY is the last two digits
641	     * of the fiscal year (starting 1 July, see {@link #fiscalYearOf(LocalDate)}) the owner's
642	     * business-day-adjusted {@code registrationDate} falls in, e.g. {@code 'FY26'}. Returns
643	     * {@code null} when the owner has no registration date, so the fiscal year cannot be derived.
644	     * This is the single definition of an owner's fiscal year, shared by every value derived on a
645	     * fiscal-year basis (see {@link #getMembershipNumber()}).
646	     *
647	     * @return the owner's fiscal year, or {@code null} when it cannot be derived
648	     */
649	    @Transient
650	    public String getFiscalYear() {
651	        if (this.registrationDate == null) {
652	            return null;
653	        }
654	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
655	    }
656	
657	    /**
658	     * Returns this owner's membership number formatted as {@code '<customerCode>-M<YY>'}, where YY is
659	     * the last two digits of the fiscal year (see {@link #fiscalYearOf(LocalDate)}) the owner's
660	     * business-day-adjusted {@code registrationDate} falls in, e.g. {@code 'NSW-A1B2C3D4-M26'}.
661	     * Returns {@code null} when the owner has no customer code or registration date.
662	     *
663	     * @return the owner's membership number, or {@code null} when it cannot be derived
664	     */
665	    @Transient
666	    public String getMembershipNumber() {
667	        if (this.customerCode == null || this.registrationDate == null) {
668	            return null;
669	        }
670	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
671	    }
672	
673	    /**
674	     * Returns this owner's check digit: a single Luhn check digit (0-9) over the digits contained in
675	     * the owner's customerCode. Returns {@code null} when the owner has no customer code.
676	     *
677	     * @return the owner's check digit, or {@code null} when it has no customer code
678	     */
679	    @Transient
680	    public Integer getCheckDigit() {
681	        if (this.customerCode == null) {
682	            return null;
683	        }
684	        String code = this.customerCode;
685	        int sum = 0;
686	        boolean dbl = true;
687	        for (int i = code.length() - 1; i >= 0; i--) {
688	            char c = code.charAt(i);
689	            if (c < '0' || c > '9') {
690	                continue;
691	            }
692	            int d = c - '0';
693	            if (dbl) {
694	                d *= 2;
695	                if (d > 9) {
696	                    d -= 9;
697	                }
698	            }
699	            sum += d;
700	            dbl = !dbl;
701	        }
702	        return (10 - (sum % 10)) % 10;
703	    }
704	
705	    /**
706	     * Returns this owner's age band, derived from {@code birthDate} computed against
707	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
708	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
709	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
710	     * band cannot be derived. This is the single definition of an owner's age band.
711	     *
712	     * @return the owner's age band, or {@code null} when it cannot be derived
713	     */
714	    @Transient
715	    public String getAgeBand() {
716	        if (this.birthDate == null || this.registrationDate == null) {
717	            return null;
718	        }
719	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
720	        if (age < 18) {
721	            return "MINOR";
722	        }
723	        if (age < 65) {
724	            return "ADULT";
725	        }
726	        return "SENIOR";
727	    }
