371	    /**
372	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
373	     * The address is normalized in place (so a required-field check that follows rejects an
374	     * address blank after normalization), the required fields are checked, the telephone and
375	     * email are normalized in place, and the resulting owner is rejected when its derived
376	     * identity key already belongs to another owner. Each rule
377	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
378	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
379	     * to be mapped and saved.
380	     *
381	     * @param ownerFieldsDto the submitted owner fields, normalized in place
382	     */
383	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
384	        applyAddress(ownerFieldsDto);
385	        validateRequiredFields(ownerFieldsDto);
386	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
387	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
388	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
389	        rejectDuplicateIdentity(ownerFieldsDto);
390	        rejectCityAtCapacity(ownerFieldsDto.getCity());
391	        rejectDailyLimitExceeded(registrationDate);
392	    }
