435	    /**
436	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
437	     * falls on a business day. The date supplied on the request is used when present, otherwise the
438	     * server's current date is used. When that effective date lands on a Saturday, Sunday or listed
439	     * public holiday it is rolled forward to the next non-holiday business day; a non-holiday weekday
440	     * is left unchanged. This single adjusted date
441	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
442	     * membership number's year segment, the per-day create limit) is computed against.
443	     *
444	     * A supplied registration date later than the server's current date is rejected with an
445	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
446	     *
447	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
448	     * @return the effective registration date rolled forward to the next business day
449	     */
450	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
451	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
452	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
453	            throw new InvalidFieldsException(List.of("registrationDate"));
454	        }
455	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
456	        return toBusinessDay(effective);
457	    }
458	
459	    /**
460	     * The fixed public holidays the business-day roll skips. A date landing on any of these is
461	     * advanced, along with weekends, until it reaches the next non-holiday business day.
462	     */
463	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
464	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
465	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
466	        LocalDate.parse("2026-12-28"));
467	
468	    /**
469	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
470	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
471	     * date already on such a business day is returned unchanged.
472	     *
473	     * @param date the date to adjust
474	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
475	     */
476	    private LocalDate toBusinessDay(LocalDate date) {
477	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
478	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
479	                || PUBLIC_HOLIDAYS.contains(date)) {
480	            date = date.plusDays(1);
481	        }
482	        return date;
483	    }
