485	    /**
486	     * The maximum number of owners that may be created on a single day. Once this many owners
487	     * already carry today's {@code registrationDate}, no further owner may be created today.
488	     */
489	    private static final long DAILY_OWNER_LIMIT = 100L;
490	
491	    /**
492	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
493	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
494	     * date the new owner would be stored with, so owners are capped per business day. When the limit
495	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
496	     * advice renders as a 429 Too Many Requests response.
497	     *
498	     * @param registrationDate the adjusted business-day registration date of the owner being created
499	     */
500	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
501	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
502	            throw new DailyOwnerLimitExceededException(registrationDate);
503	        }
504	    }
