521	    /**
522	     * The number of owners that may carry a single day's {@code registrationDate} before that day
523	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
524	     * the create and read responses report {@code bulkSignupWarning} true for that date.
525	     */
526	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
527	
528	    /**
529	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
530	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
531	     * count is taken against the same adjusted date owners are stored with, mirroring the
532	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
533	     *
534	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
535	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
536	     */
537	    private boolean bulkSignupWarning(LocalDate registrationDate) {
538	        if (registrationDate == null) {
539	            return false;
540	        }
541	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
542	    }
