544	    /**
545	     * The maximum number of owners a single city may hold. Once a city already contains this
546	     * many owners, no further owner may be created in it.
547	     */
548	    private static final long CITY_OWNER_CAPACITY = 50L;
549	
550	    /**
551	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
552	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
553	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
554	     * which the exception advice renders as a 409 Conflict response.
555	     *
556	     * @param city the city of the owner being created
557	     */
558	    private void rejectCityAtCapacity(String city) {
559	        long count = this.clinicService.findAllOwners().stream()
560	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
561	            .count();
562	        if (count >= CITY_OWNER_CAPACITY) {
563	            throw new CityCapacityExceededException(city);
564	        }
565	    }
