627	    /**
628	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
629	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it is not a hard
630	     * household duplicate. A member that declared its household via {@code sharesHousehold} is a
631	     * deliberate addition to a known household, not a suspected duplicate, so it is never flagged.
632	     * Otherwise it is a possible duplicate when an existing owner shares its {@code lastName}
633	     * (compared case-insensitively) and its {@code postcode} while carrying a different (normalized)
634	     * {@code telephone}. When such an owner is found, {@code possibleDuplicate} is set {@code true}
635	     * and {@code possibleDuplicateOf} to the matching owner's id; otherwise {@code possibleDuplicate}
636	     * is set {@code false} and no matching id is recorded. An owner without a postcode can share no
637	     * postcode and is never a possible duplicate.
638	     *
639	     * @param owner the owner being created, already carrying its normalized telephone and postcode
640	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
641	     */
642	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
643	        owner.setPossibleDuplicate(false);
644	        owner.setPossibleDuplicateOf(null);
645	        if (sharesHousehold(ownerFieldsDto)) {
646	            return;
647	        }
648	        findPossibleDuplicate(owner).ifPresent(existing -> {
649	            owner.setPossibleDuplicate(true);
650	            owner.setPossibleDuplicateOf(existing.getId());
651	        });
652	    }
653	
654	    /**
655	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
656	     * duplicate: an owner sharing its {@code lastName} (compared case-insensitively) and its
657	     * {@code postcode} while carrying a different (normalized) {@code telephone}. This is the single
658	     * definition of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records the
659	     * outcome on the owner. An owner without a postcode can share no postcode and matches nothing, so
660	     * {@link java.util.Optional#empty()} is returned.
661	     *
662	     * @param owner the owner being created, already carrying its normalized telephone and postcode
663	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
664	     */
665	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
666	        if (owner.getPostcode() == null) {
667	            return java.util.Optional.empty();
668	        }
669	        return this.clinicService.findAllOwners().stream()
670	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
671	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
672	                && owner.getPostcode().equals(existing.getPostcode())
673	                && !owner.getTelephone().equals(existing.getTelephone()))
674	            .findFirst();
675	    }
