704	    /**
705	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
706	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
707	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
708	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
709	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
710	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
711	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
712	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
713	     *
714	     * @param telephone the submitted telephone value
715	     * @return the normalized E.164 telephone
716	     */
717	    private String normalizeTelephone(String telephone) {
718	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
719	        String e164;
720	        if (cleaned.startsWith("+")) {
721	            e164 = "+" + cleaned.substring(1);
722	        } else {
723	            String national = cleaned;
724	            if (national.startsWith("0")) {
725	                national = national.substring(1);
726	            }
727	            e164 = "+61" + national;
728	        }
729	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
730	            throw new InvalidFieldsException(List.of("telephone"));
731	        }
732	        validateNationalNumberLength(e164);
733	        return e164;
734	    }
735	
736	    /**
737	     * Validates the national-number length of an already syntactically valid E.164 telephone
738	     * against its country code. When the number carries a country code this application recognizes
739	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
740	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
741	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
742	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
743	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
744	     * that is not recognized carries no per-country length rule and is left to the general
745	     * 8-to-15-digit E.164 check.
746	     *
747	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
748	     */
749	    private void validateNationalNumberLength(String e164) {
750	        String countryCode = Owner.countryCodeOf(e164);
751	        if (countryCode == null) {
752	            return;
753	        }
754	        int nationalLength = e164.length() - 1 - countryCode.length();
755	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
756	            throw new InvalidFieldsException(List.of("telephone"));
757	        }
758	    }
759	
760	    /**
761	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
762	     * and a domain containing at least one dot, none of the parts holding whitespace or a
763	     * second {@code @}.
764	     */
765	    private static final java.util.regex.Pattern EMAIL_PATTERN =
766	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
767	
768	    /**
769	     * Disposable email domains an owner may not register with. An email whose domain (compared
770	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
771	     */
772	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
773	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
774	
775	    /**
776	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
777	     * accepted and returned unchanged. When present it must be a syntactically valid address
778	     * whose domain is not on the disposable-domain blocklist (see
779	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
780	     * present but syntactically invalid or on a disposable domain an
781	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
782	     * response naming the {@code email} field.
783	     *
784	     * @param email the submitted email value, or {@code null} when omitted
785	     * @return the lower-cased email, or {@code null} when none was supplied
786	     */
787	    private String normalizeEmail(String email) {
788	        if (email == null) {
789	            return null;
790	        }
791	        String trimmed = email.trim();
792	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
793	            throw new InvalidFieldsException(List.of("email"));
794	        }
795	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
796	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
797	            throw new InvalidFieldsException(List.of("email"));
798	        }
799	        return canonicalEmail(trimmed);
800	    }
801	
802	    /**
803	     * Reduces an email to the canonical form used both to store it and to compare it against
804	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
805	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
806	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
807	     * value read back off an existing owner without risk of rejecting it. This is the single
808	     * definition of email identity: two emails denote the same address exactly when they
809	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
