866	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
867	     */
868	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
869	        if (sharesHousehold(ownerFieldsDto)) {
870	            return;
871	        }
872	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
873	        if (householdId == null) {
874	            return;
875	        }
876	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
877	        boolean taken = householdMembers(householdId).stream()
878	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
879	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
880	        if (taken) {
881	            throw new DuplicateIdentityException(identityKey);
882	        }
883	    }
