957	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
958	     */
959	    private String shaHex(String input, int hexChars) {
960	        return Owner.sha256Hex(input).substring(0, hexChars).toUpperCase(java.util.Locale.ROOT);
