1059	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1060	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1061	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1062	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1063	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1064	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1065	     * everywhere an address is stored or compared.
1066	     *
1067	     * @param address the submitted address value, or {@code null}
1068	     * @return the normalized address, never {@code null}
1069	     */
1070	    private String normalizeAddress(String address) {
1071	        if (address == null) {
1072	            return "";
1073	        }
1074	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1075	        if (collapsed.isEmpty()) {
1076	            return "";
1077	        }
1078	        String[] tokens = collapsed.split(" ");
1079	        StringBuilder sb = new StringBuilder(collapsed.length());
1080	        for (int i = 0; i < tokens.length; i++) {
1081	            if (i > 0) {
1082	                sb.append(' ');
1083	            }
1084	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1085	        }
1086	        return sb.toString();
1087	    }
